export const messages = { en: english, it: { ...english, ...italian } } as const;

export function translate(locale: Locale, key: MessageKey, values: Record<string, string | number> = {}) {
  const value = messages[locale][key] ?? messages.en[key];
  return value.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`));
}
